import {test,expect} from '@playwright/test';
import {prepareReadyPage} from '@lib/golden-ready-page';
test('G05 synthetic seed',async({page})=>{const result=await test.step('Stage 1: setContent',()=>prepareReadyPage({page}));await test.step('Stage 2: assertions',async()=>{await expect(page.getByRole('heading')).toHaveText('Whippet ready'); await expect(page.getByRole('heading')).toBeVisible(); expect(result.heading).toBe('Whippet ready');});});

