import {test,expect} from '@playwright/test';
import {prepareLoginRoleGap} from '@lib/golden-login-role-gap';
test('G06 synthetic seed',async({page})=>{const result=await test.step('Stage 1: setContent',()=>prepareLoginRoleGap({page}));await test.step('Stage 2: assertions',async()=>{await expect(page.getByLabel('帳號')).toHaveValue(''); await expect(page.getByLabel('密碼')).toHaveValue(''); await expect(page.getByRole('button',{name:'登入'})).toBeDisabled(); await expect(page.getByRole('status')).toHaveText('缺少 Workspace 角色與 credentials；未執行登入'); expect(result).toEqual({status:'blocked',reason:'workspace_role_not_configured'});});});

